      <article class="panel"><h2>已知线索</h2><div id="clues" class="chips"></div></article>
      <article class="panel"><h2>玩家公开起点</h2><div id="player" class="detail">—</div></article>
      <article class="panel"><h2>本楼玩家手记</h2><div id="memoRead" class="detail">—</div></article>
    </section>

    <section id="actions" class="actions">
      <button data-index="0"><b>读取中</b><small>等待当前任务</small></button>
      <button data-index="1"><b>读取中</b><small>等待当前区域</small></button>
      <button data-index="2"><b>读取中</b><small>等待当前线索</small></button>
    </section>

    <section class="memo">
      <input id="memoInput" maxlength="80" placeholder="写一条只属于本楼快照的玩家手记">
